// ===============================
// Advanced Translation Formatter
// ===============================

const input = $input.first().json.output;

if (!input) {
    throw new Error("AI Agent output not found.");
}

const detectedLanguage = input.detected_language || "Unknown";
const translations = input.translations || {};
const originalText = input.original_text || translations[detectedLanguage] || "";

// -------------------------------
// Create Safe Filename
// -------------------------------

const now = new Date();

const timestamp =
`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}_${String(now.getHours()).padStart(2,'0')}-${String(now.getMinutes()).padStart(2,'0')}-${String(now.getSeconds()).padStart(2,'0')}`;

const title = (originalText || "Translation")
.replace(/[^\p{L}\p{N}\s]/gu,"")
.trim()
.split(/\s+/)
.slice(0,6)
.join("_")
|| "Translation";

const fileName = `${title}_${timestamp}.txt`;

// -------------------------------
// Statistics
// -------------------------------

const languageNames = Object.keys(translations);
const totalLanguages = languageNames.length;

// -------------------------------
// Header
// -------------------------------

let output = "";

output += "============================================================\n";
output += "             MULTI LANGUAGE TRANSLATION REPORT\n";
output += "============================================================\n\n";

output += `Generated On      : ${now.toLocaleString()}\n`;
output += `Detected Language : ${detectedLanguage}\n`;
output += `Languages         : ${totalLanguages}\n`;
output += `File Name         : ${fileName}\n\n`;

output += "============================================================\n";
output += "ORIGINAL TEXT\n";
output += "============================================================\n\n";

output += originalText + "\n\n";

// -------------------------------
// Language Index
// -------------------------------

output += "============================================================\n";
output += "LANGUAGE INDEX\n";
output += "============================================================\n\n";

languageNames.forEach((lang, index) => {
    output += `${String(index + 1).padStart(2,'0')}. ${lang}\n`;
});

output += "\n";

// -------------------------------
// Translations
// -------------------------------

output += "============================================================\n";
output += "TRANSLATIONS\n";
output += "============================================================\n\n";

languageNames.forEach((language, index) => {

    const translation = String(translations[language]).trim();

    output += "------------------------------------------------------------\n";
    output += `${index + 1}. ${language}\n`;
    output += "------------------------------------------------------------\n";
    output += translation + "\n\n";

});

// -------------------------------
// Footer
// -------------------------------

output += "============================================================\n";
output += `End of Translation Report\n`;
output += "Generated Automatically by Multi Language Translator Bot\n";
output += "============================================================";

// -------------------------------
// Return
// -------------------------------

return [
{
json:{

fileName,

mimeType:"text/plain",

text:output,

totalLanguages,

detectedLanguage,

generatedAt:now.toISOString()

}
}
];
